def generate_keys(p, q, e):
    n = p * q
    phi = (p-1) * (q-1)
    d = pow(e, -1, phi)
    return (n, e), (n, d)

def rsa_encrypt(plain_int, pub_key):
    n, e = pub_key
    return pow(plain_int, e, n)

def rsa_decrypt(cipher_int, priv_key):
    n, d = priv_key
    return pow(cipher_int, d, n)
